// Next lesson: the line above the prompt saying what the teacher teaches now and next, read from their timetable file.
// A lesson whose run sheet a planning window handed over (the run tool) becomes a dark card with a bar a task.
// It runs by itself: the first task starts with the lesson and each follows on when the one before runs out,
// with a soft chime (or Alice, or nothing: /lessons sound). ▶ jumps to a task, ✓ ends the one running.
// /today opens the day as a tab; /lessons try runs a pretend lesson. None of it costs a turn.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Lesson, LessonRun, Play, RunTask } from '../types'
import { CARD, DIM, GREEN, GREY_PILL, TEXT, header, hexOf, task as paintTask } from './card'
import type { Seg, TaskLook } from './card'
import { asRun, lessonKey, paceAt, runFor, slots } from './run'
import type { Slot } from './run'
import { cardSvg } from './svg'
import type { SvgRow } from './svg'
import {
  DAYS,
  addDays,
  dateFrom,
  dayLabel,
  describeDay,
  firstAfter,
  isoOf,
  lessonsOn,
  longDay,
  msOf,
  parseTimetable,
  periodLabel,
  stripAt,
} from './timetable'
import type { Strip } from './timetable'

const timetable = atom({ plugin: 'next-lesson', key: 'timetable' } as const, null)
const problem = atom({ plugin: 'next-lesson', key: 'problem' } as const, '')
const minute = atom({ plugin: 'next-lesson', key: 'minute' } as const, 0)
const hidden = atom({ plugin: 'next-lesson', key: 'isHidden' } as const, false)
const runsAtom = atom({ plugin: 'next-lesson', key: 'runs' } as const, [])
const playAtom = atom({ plugin: 'next-lesson', key: 'play' } as const, null)
const beat = atom({ plugin: 'next-lesson', key: 'beat' } as const, 0)
const trialAtom = atom({ plugin: 'next-lesson', key: 'trial' } as const, null)

// The timetable file, under the home folder until /lessons timetable names another (kept in the shared settings).
const DEFAULT_TIMETABLE = 'Timetable.md'
// Shared by every window: the run sheets, what was last sounded, the sound setting, and whether a lesson is on.
const DIR = '.claude/next-lesson'
const HIDDEN_KEY = 'isHidden'
const TOOL = 'mcp__next-lesson__run'
const PANE = 'today'
const PANE_TITLE = '🟢 Today'
const TICK_MS = 20 * 1000
const FRAME_MS = 100 // the running bar's shimmer and fill
const SOON_MS = 10 * 60 * 1000 // "Next" turns amber this close to a lesson
const PREVIEW_MS = 15 * 60 * 1000 // a lesson's card shows this long before it starts
const WARN_MS = 5 * 60 * 1000 // "Five minutes left", with the voice on
const KEEP_RUN_DAYS = 14
const TITLE_MAX = 28 // a task's title on its row, cut at a word, never with "…"
const BUTTON_COLUMNS = 3
// The Mac's own soft Glass chime, played from macOS itself so nothing of Apple's is shipped; chosen over a voice
// for the classroom.
const CHIME = '/System/Library/Sounds/Glass.aiff'
const CHIME_VOLUME = '0.6'
// Alice, a clear British ElevenLabs voice. Only with /lessons sound voice, and only with an ELEVENLABS_API_KEY.
const VOICE_ID = 'Xb7hH8MSUJpSbSDYk0k2'
const VOICE_MODEL = 'eleven_multilingual_v2'
const FIVE_LEFT = 'Five minutes left.'
const ALL_DONE = 'All tasks done.'
const AMBER = '#E8A33D'
const QUIET = '#888888'
const DONE_BG = '#BFE5C8'
const AHEAD_BG = '#E4E4E4'
// Short names and colours for common class names; any other class gets its own name and a colour (classOf).
const CLASSES: Record<string, { short: string; colour: string }> = {
  'upper sixth': { short: 'U6', colour: '#8AA4E8' },
  'lower sixth': { short: 'L6', colour: '#7FC8C8' },
  'fifth form': { short: '5 Form', colour: '#A78BFA' },
  'fourth form': { short: '4 Form', colour: '#9FD18B' },
}

type Sound = 'chime' | 'voice' | 'off'

const GUIDE = [
  "The teacher's lesson strip (the next-lesson mod): when you finish or change a run sheet for one of their lessons, also",
  'hand it to the strip with mcp__next-lesson__run: the class as the timetable names it, the date, the period',
  "(P7, P4+P5), and each task in order with a short title in the plan's words (28 characters at most), a one-word",
  'label (Quiz, Starter, Essay, Listen), its minutes, or for a quiz or exam question its marks (one mark, one',
  'minute), and one sentence of detail. In the lesson each task is a bar above their prompt, one after another.',
].join(' ')

const RUN_DESCRIPTION = [
  "Hand a lesson's run sheet to the teacher's lesson strip. In that lesson each task is a bar on a card above the prompt;",
  'the first starts with the lesson and each follows on as the one before runs out (a tick a mark for a quiz), with',
  'a soft chime. Checked against their timetable: the class must be on it at that date and period. Handing over the',
  'same lesson again replaces it.',
].join(' ')

// The surface's element table, as $.ui.resolve gives it; Raster is the terminal's alone, Svg the desktop's and phone's.
type T = { Box: any; Button: any; Text: any; Raster?: any; Svg?: any }

// A bar on screen that moves: what the frame timer repaints between redraws, and what it sounds when it fills.
type LiveBar = { key: string; look: TaskLook; at: number; minutes: number; label: string; ticks: number; accent: number; soundId: string; line: string }
let live: { requestId: string; bars: LiveBar[] } | null = null
let home = ''
// The lesson and task last seen by the tick, so a task that moves on redraws the card in every window.
let lastPace = ''
let timetableMtime = -1
let runsMtime = -1

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await $.command.register({
      name: 'lessons',
      description: 'Your lessons: /lessons for today, /lessons tomorrow or a day (fri), /lessons try (a pretend lesson), /lessons sound chime, voice or off, /lessons timetable <file>, /lessons hide or show',
    })
    await $.command.register({ name: 'today', description: "Today's lessons and their tasks, as a tab beside your clip list and panel" })
    await $.tool.register({
      name: 'run',
      description: RUN_DESCRIPTION,
      inputSchema: {
        type: 'object',
        properties: {
          class: { type: 'string', description: 'As the timetable names it: "Lower Sixth", "Upper Sixth", "Fifth Form", "Fourth Form".' },
          date: { type: 'string', description: '"2026-11-02" or "Mon 2 Nov".' },
          period: { type: 'string', description: '"P7", or "P4+P5" for a double.' },
          tasks: {
            type: 'array',
            description: 'In order.',
            items: {
              type: 'object',
              properties: {
                title: { type: 'string', description: "A few words, the plan's own, 28 characters at most: \"Era 1 from the front\"." },
                label: { type: 'string', description: 'One word for the chip on its bar: "Quiz", "Starter", "Essay", "Listen".' },
                minutes: { type: 'number', description: 'Its length; leave out for a quiz or question given in marks.' },
                marks: { type: 'number', description: "A quiz or exam question's marks: a tick each, one mark one minute." },
                start: { type: 'string', description: '"14:43" when the plan gives it.' },
                detail: { type: 'string', description: 'One sentence: what the pupils do.' },
              },
              required: ['title'],
            },
          },
        },
        required: ['class', 'date', 'period', 'tasks'],
      },
    })
    if ((await $.store.get(HIDDEN_KEY)) === true) await update($, hidden, () => true)
    await load($)
    const startedAt = Math.floor((await $.clock.now()) / 60000)
    await update($, minute, () => startedAt)
    $.clock.every(TICK_MS, () => void tick($))
    $.clock.every(FRAME_MS, () => void frame($))

    return started
  })

  on('prompt.compose', async ($, e, next) => {
    const composed = await next(e)

    return { ...composed, sections: [...composed.sections, { id: 'next-lesson:guide', text: GUIDE, scope: 'session' }] }
  })

  // Matched by name in the hook: the tool is this mod's own, registered above, so its type is not listed yet.
  on('tool.call', async ($, e, next) => {
    if (String(e.tool) !== TOOL) return next(e)
    await load($)
    const t = await read($, timetable)
    if (!t) return { deny: (await read($, problem)) || 'The timetable could not be read.' }
    const { run, why } = asRun(e as unknown as Record<string, unknown>, t, new Date(await $.clock.now()))
    if (!run) return { deny: why ?? 'That run sheet could not be read.' }
    const kept = await saveRun($, run)
    // With the voice on, Alice's lines are made now, while nobody waits for them; the chime needs nothing made.
    if ((await soundOf($)) === 'voice') void prepareVoice($, run)

    return { result: `Handed to the lesson strip: ${run.cls} ${run.period}, ${longDay(run.date)}, ${run.tasks.length} tasks (${kept} lessons' run sheets kept).` }
  })

  on('command.run', { command: 'lessons' }, async ($, e) => {
    const arg = e.args.trim().toLowerCase()
    if (arg === 'hide' || arg === 'off' || arg === 'show' || arg === 'on') {
      const isHidden = arg === 'hide' || arg === 'off'
      await update($, hidden, () => isHidden)
      await $.store.set(HIDDEN_KEY, isHidden)

      return { text: isHidden ? 'Lesson strip hidden. /lessons show brings it back.' : 'Lesson strip shown above the prompt.' }
    }
    if (arg === 'try') {
      const trial = await startTrial($)

      return { text: `A pretend ${trial.lesson.cls} lesson is running on the card above your prompt: three tasks of a minute each, one after another, a chime as each gives way. ▶ jumps to a task, ✓ ends the one running.` }
    }
    if (/^timetable\b/.test(arg)) {
      const given = e.args.trim().replace(/^timetable\s*/i, '').replace(/^["']|["']$/g, '')
      if (given) {
        await saveSettings($, { timetable: given })
        timetableMtime = -1
      }
      await load($)
      const t = await read($, timetable)
      const path = await timetablePathOf($)
      const count = t ? Object.values(t.week).reduce((n, day) => n + Object.keys(day).length, 0) : 0

      return { text: t ? `Reading your timetable from ${path}: ${count} periods a week.` : (await read($, problem)) || `Nothing read from ${path}.` }
    }
    const soundAsked = /^(sound|voice)\b/.test(arg) ? soundIn(arg) : undefined
    if (soundAsked) {
      await saveSettings($, { sound: soundAsked })
      const says: Record<Sound, string> = {
        chime: 'A soft chime as each task gives way to the next.',
        voice: 'Alice says each task as it starts, and "Five minutes left" near the end of a lesson.',
        off: 'No sound: the card just moves on.',
      }

      return { text: `${says[soundAsked]} (/lessons sound chime, voice or off)` }
    }
    await load($)
    const t = await read($, timetable)
    if (!t) return { text: (await read($, problem)) || 'The timetable has not been read yet.' }
    const now = new Date(await $.clock.now())
    const day = dayAsked(arg, now)
    if (!day) return { text: 'Type /lessons, /lessons tomorrow, a day (/lessons fri), /lessons try, /lessons sound chime, voice or off, /lessons timetable <file>, or /lessons hide.' }

    return { text: describeDay(t, day) }
  })

  on('command.run', { command: 'today' }, async ($, e) => {
    if (/^(close|hide)$/.test(e.args.trim().toLowerCase())) {
      await $.ui.close({ id: PANE })

      return { text: 'Today tab closed. /today opens it again.' }
    }
    await load($)
    await $.ui.open({ id: PANE, title: PANE_TITLE, columns: 56, rows: 30 })

    return { text: 'Today is open as a tab at the top, beside your clip list and panel. /today close shuts it.' }
  })

  // The band is shared: whatever another mod draws there (the build progress rows) stays, below this.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, hidden))) return next(e)
    const ui = $.ui.resolve(e)
    const mine = await band($, ui, e.surface === 'terminal', e.requestId, e.props.bodyColumns ?? 100)
    if (!mine) return next(e)
    const below = await next(e)

    return (
      <ui.Box flexDirection="column">
        {mine}
        {below}
      </ui.Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => todayPane($, $.ui.resolve(e)))
}

// "sound chime", "sound voice", "sound off"; the older "voice on" and "voice off" still work.
function soundIn(arg: string): Sound | undefined {
  if (/\bvoice\b/.test(arg) && /\bon\b/.test(arg)) return 'voice'
  if (/^voice\b/.test(arg) && /\boff\b/.test(arg)) return 'chime'
  if (/\bchime\b/.test(arg)) return 'chime'
  if (/\bvoice\b/.test(arg)) return 'voice'
  if (/\b(off|quiet|none)\b/.test(arg)) return 'off'

  return undefined
}

async function soundOf($: EngineInterface): Promise<Sound> {
  const s = (await readShared($, 'settings.json')) as { sound?: Sound; voice?: boolean } | null
  if (s?.sound === 'chime' || s?.sound === 'voice' || s?.sound === 'off') return s.sound

  return s?.voice === false ? 'off' : 'chime'
}

// Every tick: a changed timetable or run sheet is read, the line moves on, the shared "lesson on" note is
// written for the build progress mod, and (with the voice on) "Five minutes left" is said when due.
async function tick($: EngineInterface) {
  await load($)
  const now = await $.clock.now()
  const m = Math.floor(now / 60000)
  if (m !== (await read($, minute))) await update($, minute, () => m)
  const trial = await read($, trialAtom)
  if (trial && now >= msOf(trial.lesson.date, trial.lesson.end)) await update($, trialAtom, () => null)
  const t = await read($, timetable)
  if (!t) return
  const s = stripAt(t, new Date(now))
  const lesson = s.kind === 'now' ? { cls: s.lesson.cls, period: periodLabel(s.lesson), until: s.lesson.end } : null
  await writeShared($, 'now.json', { lesson, at: now })
  if (s.kind === 'now') await warnNearEnd($, s.lesson, now)
  const isTrial = trial !== null && now < msOf(trial.lesson.date, trial.lesson.end)
  const focus = isTrial ? trial.lesson : s.kind === 'now' ? s.lesson : undefined
  const run = isTrial ? trial.run : focus ? runFor(await read($, runsAtom), focus) : undefined
  if (focus && run) await soundFollowOn($, focus, run, now)
}

// A task that has just run out by itself is sounded in from here too, in case a redraw on the minute took the
// running bar off the frame timer before it saw the bar fill. The same id as the frame's, so it sounds once.
async function soundFollowOn($: EngineInterface, l: Lesson, run: LessonRun, now: number) {
  playCopy = await read($, playAtom)
  const { current, play } = paceOf(l, run, now)
  const seen = `${lessonKey(l)}|${current}`
  if (seen !== lastPace) {
    const isFirst = lastPace === ''
    lastPace = seen
    if (!isFirst) await update($, beat, b => b + 1)
  }
  if (current <= play.task || play.endedAt !== undefined) return
  const ended = slots(run, play.task, play.at).find(x => x.i === current - 1)
  if (!ended || now - ended.to > 60000) return
  const next = run.tasks[current]
  await announce($, `${lessonKey(l)}|after${current - 1}|${Math.round(ended.to / 1000)}`, next ? spokenLine(current, next) : ALL_DONE)
}

// Every frame: the running bar moves on (fill, chip, shimmer) by repainting its cells in place; when it fills,
// the next task is sounded in and the card redraws with it running.
async function frame($: EngineInterface) {
  if (!live) return
  const now = await $.clock.now()
  for (const bar of live.bars) {
    const fraction = (now - bar.at) / (bar.minutes * 60000)
    if (fraction >= 1) {
      live = null
      await update($, beat, b => b + 1)
      await announce($, bar.soundId, bar.line)

      return
    }
    const look = { ...bar.look, ...running(bar, fraction), phase: Math.floor(now / 80) }
    const done = await $.ui.blit({ requestId: live.requestId, key: bar.key, cells: paintTask(look), columns: look.width, rows: 1 }).catch(() => ({ deny: 'gone' }))
    if ('deny' in done && done.deny) {
      live = null

      return
    }
  }
}

// "Five minutes left", with the voice on only: a chime then would sound like a task changing.
async function warnNearEnd($: EngineInterface, l: Lesson, now: number) {
  const end = msOf(l.date, l.end)
  if (end - msOf(l.date, l.start) < 20 * 60000 || (await soundOf($)) !== 'voice') return
  const at = end - WARN_MS
  if (now < at || now - at >= 60000) return
  await announce($, `${lessonKey(l)}|five`, FIVE_LEFT)
}

// A change in the lesson, sounded once across every window (the shared note is written first, so another
// window finds it done): the chime, Alice saying the line, or nothing, as /lessons sound has it.
async function announce($: EngineInterface, id: string, line: string) {
  const sound = await soundOf($)
  if (sound === 'off') return
  const done = ((await readShared($, 'spoken.json')) as { ids?: string[] } | null)?.ids ?? []
  if (done.includes(id)) return
  await writeShared($, 'spoken.json', { ids: [...done, id].slice(-60) })
  if (sound === 'chime') await $.process.run(['afplay', '-v', CHIME_VOLUME, CHIME], { timeoutMs: 10000 }).catch(() => undefined)
  else await speak($, line)
}

// Plays a line in Alice's voice, making it first if it has not been made. With no file and no way to make one
// (offline, or no key), nothing is said: a robotic stand-in in front of a class is worse than silence.
async function speak($: EngineInterface, text: string) {
  const file = await voiceFile($, text)
  if (file) await $.process.run(['afplay', file], { timeoutMs: 30000 }).catch(() => undefined)
  else $.ui.toast('Alice could not be reached (ElevenLabs), so that line was not said')
}

function spokenLine(i: number, k: RunTask): string {
  return `Task ${i + 1}. ${plain(k.title)}.`
}

// Every line a run sheet will say, made ahead: each task as it starts, the five-minute warning, the end.
async function prepareVoice($: EngineInterface, run: LessonRun) {
  for (const text of [...run.tasks.map((k, i) => spokenLine(i, k)), FIVE_LEFT, ALL_DONE]) await voiceFile($, text)
}

// The line's sound file, kept by voice and words, made with ElevenLabs the first time (the key comes from the
// ELEVENLABS_API_KEY the shell holds; it never sits in this file). About 40 characters of the account's allowance a line.
async function voiceFile($: EngineInterface, text: string): Promise<string | undefined> {
  const dir = `${await homeOf($)}/${DIR}/voice`
  const path = `${dir}/${hashOf(`${VOICE_ID}|${VOICE_MODEL}|${text}`)}.mp3`
  if (await $.fs.exists(path).catch(() => false)) return path
  await $.process.run(['mkdir', '-p', dir]).catch(() => undefined)
  const curl = [
    'curl -s -o "$1" -w "%{http_code}" -X POST',
    `"https://api.elevenlabs.io/v1/text-to-speech/${VOICE_ID}?output_format=mp3_44100_128"`,
    '-H "xi-api-key: $ELEVENLABS_API_KEY" -H "Content-Type: application/json" --data-binary @-',
  ].join(' ')
  const made = await $.process
    .run(['/bin/sh', '-c', curl, 'sh', path], { stdin: JSON.stringify({ text, model_id: VOICE_MODEL }), timeoutMs: 30000 })
    .catch(() => null)
  if (made?.stdout.trim() === '200') return path
  await $.process.run(['rm', '-f', path]).catch(() => undefined)

  return undefined
}

// A short name for a line's file: the same words in the same voice always find the same file.
function hashOf(text: string): string {
  let h = 5381
  for (let i = 0; i < text.length; i += 1) h = ((h << 5) + h + text.charCodeAt(i)) >>> 0

  return `${h.toString(36)}-${text.length}`
}

async function homeOf($: EngineInterface): Promise<string> {
  if (home) return home
  const root = $.plugin.root
  const at = root.indexOf('/.claude/')
  home = at >= 0 ? root.slice(0, at) : (await $.process.run(['/bin/sh', '-c', 'printf %s "$HOME"'])).stdout.trim()

  return home
}

// The timetable file: the path /lessons timetable saved (absolute, ~/..., or under the home folder), else
// Timetable.md in the home folder.
async function timetablePathOf($: EngineInterface): Promise<string> {
  const h = await homeOf($)
  const saved = ((await readShared($, 'settings.json')) as { timetable?: string } | null)?.timetable?.trim()
  const given = saved || DEFAULT_TIMETABLE
  if (given.startsWith('/')) return given
  if (given.startsWith('~/')) return `${h}/${given.slice(2)}`

  return `${h}/${given}`
}

// Settings are shared by every window and kept together: a change to one keeps the others.
async function saveSettings($: EngineInterface, change: Record<string, unknown>) {
  const now = ((await readShared($, 'settings.json')) as Record<string, unknown> | null) ?? {}
  await writeShared($, 'settings.json', { ...now, ...change })
}

// Reads the timetable and the run sheets when they are new or changed; a missing timetable says so in the strip.
async function load($: EngineInterface) {
  const path = await timetablePathOf($)
  try {
    const { mtimeMs } = await $.fs.stat(path)
    if (mtimeMs !== timetableMtime) {
      timetableMtime = mtimeMs
      const parsed = parseTimetable(await $.fs.read(path))
      const isUsable = parsed.periods.length > 0 && Object.keys(parsed.week).length > 0
      await update($, timetable, () => (isUsable ? parsed : null))
      await update($, problem, () => (isUsable ? '' : `No Periods or Week table in ${path}`))
    }
  } catch {
    timetableMtime = -1
    await update($, timetable, () => null)
    await update($, problem, () => `No timetable at ${path}: type /lessons timetable and the path of your timetable file.`)
  }
  try {
    const { mtimeMs } = await $.fs.stat(`${await homeOf($)}/${DIR}/runs.json`)
    if (mtimeMs === runsMtime) return
    runsMtime = mtimeMs
    const runs = await readShared($, 'runs.json')
    await update($, runsAtom, () => (Array.isArray(runs) ? (runs as LessonRun[]) : []))
  } catch {
    // No run sheets handed over yet.
  }
}

// Keeps a lesson's run sheet in the shared file, in place of an earlier one for the same lesson; old ones go.
async function saveRun($: EngineInterface, run: LessonRun): Promise<number> {
  const disk = await readShared($, 'runs.json')
  const cutoff = isoOf(addDays(new Date(await $.clock.now()), -KEEP_RUN_DAYS))
  const others = (Array.isArray(disk) ? (disk as LessonRun[]) : []).filter(r => r.date >= cutoff && !sameLesson(r, run))
  const runs = [...others, run].sort((a, b) => a.date.localeCompare(b.date))
  await writeShared($, 'runs.json', runs)
  await update($, runsAtom, () => runs)

  return runs.length
}

function sameLesson(a: LessonRun, b: LessonRun): boolean {
  return a.cls.toLowerCase() === b.cls.toLowerCase() && a.date === b.date && a.period === b.period
}

async function readShared($: EngineInterface, name: string): Promise<unknown> {
  try {
    return JSON.parse(await $.fs.read(`${await homeOf($)}/${DIR}/${name}`))
  } catch {
    return null
  }
}

async function writeShared($: EngineInterface, name: string, value: unknown) {
  const dir = `${await homeOf($)}/${DIR}`
  try {
    await $.fs.write(`${dir}/${name}`, JSON.stringify(value))
  } catch {
    await $.process.run(['mkdir', '-p', dir]).catch(() => undefined)
    await $.fs.write(`${dir}/${name}`, JSON.stringify(value)).catch(() => undefined)
  }
}

// The band: the card when a lesson with a run sheet is on (or about to be), else one plain line.
async function band($: EngineInterface, ui: T, isTerminal: boolean, requestId: string, columns: number) {
  const { Box, Text } = ui
  await read($, minute)
  await read($, beat)
  const t = await read($, timetable)
  if (!t) {
    const why = await read($, problem)

    return why ? <Box paddingX={1}><Text dimColor wrap="wrap">{why}</Text></Box> : null
  }
  const now = await $.clock.now()
  const trial = await read($, trialAtom)
  const isTrial = trial !== null && now < msOf(trial.lesson.date, trial.lesson.end)
  const s: Strip = isTrial ? { kind: 'now', lesson: trial.lesson, leftMs: msOf(trial.lesson.date, trial.lesson.end) - now, rest: [] } : stripAt(t, new Date(now))
  const focus = s.kind === 'now' ? s.lesson : s.kind === 'next' && s.inMs <= PREVIEW_MS ? s.lesson : undefined
  const run = isTrial ? trial.run : focus ? runFor(await read($, runsAtom), focus) : undefined
  playCopy = await read($, playAtom)
  // The terminal paints the card in character cells; the desktop app and the phone draw it as a picture. (Elsewhere
  // Raster exists only as an empty stand-in, so the surface decides, not the table.)
  if (focus && run && run.tasks.length > 0 && isTerminal && ui.Raster) return card($, ui, requestId, columns, s.kind === 'now', focus, run, now)
  if (focus && run && run.tasks.length > 0 && !isTerminal && ui.Svg) return pictureCard($, ui, s.kind === 'now', focus, run, now)
  live = null

  return (
    <Box flexDirection="row" flexWrap="wrap" paddingX={1}>
      {stripLine($, ui, s, new Date(now))}
    </Box>
  )
}

// What a task's bar shows at a fraction of its time: the chip, its colours, the percentage.
function running(bar: { label: string; ticks: number; accent: number }, fraction: number): Partial<TaskLook> {
  const f = Math.max(0, Math.min(1, fraction))

  return { fraction: f, pill: `${bar.label} ${Math.min(bar.ticks, Math.floor(f * bar.ticks))}/${bar.ticks}`, pillBg: bar.accent, pillFg: 0x000000, percent: `${Math.floor(f * 100)}%` }
}

// Where a lesson is: from the task the teacher last jumped to (or the first, at the bell), each following on.
function paceOf(l: Lesson, run: LessonRun, now: number): { current: number; slot?: Slot; fraction: number; play: Play } {
  const play = playNow(l, run) ?? { key: lessonKey(l), task: 0, at: msOf(l.date, l.start) }
  const pace = paceAt(run, slots(run, play.task, play.at, play.endedAt), play.task, now)

  return { ...pace, play }
}

// The card: a header (now or next, the class, how far through), then the task running (or the first, waiting
// for the lesson) and the next one. Each row's button sits at its right end, on the card's colour.
function card($: EngineInterface, ui: T, requestId: string, columns: number, isNow: boolean, l: Lesson, run: LessonRun, now: number) {
  const { Box, Button, Text } = ui
  const Raster = ui.Raster
  const key = lessonKey(l)
  const width = Math.max(48, Math.min(columns - 2, 120))
  const rowWidth = width - BUTTON_COLUMNS
  const accent = hexOf(classOf(l.cls).colour)
  const { current, slot, fraction } = paceOf(l, run, now)
  const count = run.tasks.length
  const isAllDone = current >= count
  const shown = current < 0 ? [0] : isAllDone ? [count - 1] : current + 1 < count ? [current, current + 1] : [current]
  const titles = shown.map(i => shortTitle(run.tasks[i]!.title))
  const titleWidth = Math.max(...titles.map(x => x.length), 8)
  const bars: LiveBar[] = []

  const row = (i: number, n: number) => {
    const k = run.tasks[i]!
    const ticks = ticksOf(k)
    const label = k.label || plain(k.title).split(/\s+/)[0] || 'Task'
    const isRunning = i === current
    const isDone = i < current
    const base: TaskLook = { width: rowWidth, glyph: '○', glyphFg: DIM, title: titles[n]!, titleWidth, fraction: 0, ticks, pill: `${label} 0/${ticks}`, pillBg: GREY_PILL, pillFg: TEXT, accent, percent: '0%', phase: 0 }
    const look: TaskLook = isDone
      ? { ...base, glyph: '✓', glyphFg: GREEN, fraction: 1, pill: `✓ ${label} ${ticks}/${ticks}`, pillBg: GREEN, pillFg: 0x000000, percent: '100%' }
      : isRunning
        ? { ...base, glyph: '●', glyphFg: accent, ...running({ label, ticks, accent }, fraction), phase: Math.floor(now / 80) }
        : base
    const rasterKey = `bar-${i}`
    if (isRunning && slot) {
      const next = run.tasks[i + 1]
      bars.push({
        key: rasterKey,
        look,
        at: slot.from,
        minutes: (slot.to - slot.from) / 60000,
        label,
        ticks,
        accent,
        soundId: `${key}|after${i}|${Math.round(slot.to / 1000)}`,
        line: next ? spokenLine(i + 1, next) : ALL_DONE,
      })
    }
    // ✓ ends the running task (the next starts); ▶ jumps to a task still to come; a done task has none.
    const press = isRunning ? () => void finishTask($, l, run) : !isDone ? () => void jumpTo($, l, run, i) : undefined

    return (
      <Box key={`row-${i}`} flexDirection="row">
        <Raster key={rasterKey} columns={rowWidth} rows={1} cells={paintTask(look)} />
        {press ? (
          <Button key={isRunning ? `finish-${i}` : `start-${i}`} plain onPress={press}>
            <Text backgroundColor={hex(CARD)} color={hex(isRunning ? GREEN : TEXT)} bold>{isRunning ? ' ✓ ' : ' ▶ '}</Text>
          </Button>
        ) : (
          <Text backgroundColor={hex(CARD)}>{' '.repeat(BUTTON_COLUMNS)}</Text>
        )}
      </Box>
    )
  }

  const c = classOf(l.cls)
  const left: Seg[] = [
    { text: isNow ? '● Now  ' : '○ Next  ', fg: isNow ? accent : DIM },
    { text: ` ${c.short} ${periodLabel(l)} `, fg: 0x000000, bg: accent },
    // The class's full name, unless its chip already says it.
    ...(c.short === l.cls ? [] : [{ text: `  ${l.cls}`, fg: TEXT }]),
  ]
  const right: Seg[] = isAllDone
    ? [{ text: '✓ All tasks done', fg: GREEN }]
    : current < 0
      ? [{ text: `${count} tasks · they start with the lesson`, fg: DIM }]
      : [{ text: `Task ${current + 1} of ${count}`, fg: TEXT }]
  const rows = shown.map(row)
  live = bars.length > 0 ? { requestId, bars } : null

  return (
    <Box flexDirection="column" paddingX={1}>
      <Raster key="card-head" columns={width} rows={1} cells={header(width, left, right)} />
      {rows}
    </Box>
  )
}

// The card as a picture where the surface draws SVG (the desktop app, the phone): rounded and shaded like the
// desktop app's own panels, moving by itself; under it, buttons to end the running task or start the next now.
function pictureCard($: EngineInterface, ui: T, isNow: boolean, l: Lesson, run: LessonRun, now: number) {
  const { Box, Button } = ui
  const Svg = ui.Svg
  const { current, slot, fraction } = paceOf(l, run, now)
  const count = run.tasks.length
  const isAllDone = current >= count
  const shown = current < 0 ? [0] : isAllDone ? [count - 1] : current + 1 < count ? [current, current + 1] : [current]
  const labelOf = (k: RunTask) => k.label || plain(k.title).split(/\s+/)[0] || 'Task'
  const rows: SvgRow[] = shown.map(i => {
    const k = run.tasks[i]!
    const isRunning = i === current && slot !== undefined

    return {
      state: i < current ? 'done' : isRunning ? 'running' : 'waiting',
      title: shortTitle(k.title),
      label: labelOf(k),
      ticks: ticksOf(k),
      fraction: isRunning ? fraction : i < current ? 1 : 0,
      secondsLeft: isRunning ? (slot.to - now) / 1000 : 0,
    }
  })
  const c = classOf(l.cls)
  const right = isAllDone ? '✓ All tasks done' : current < 0 ? `${count} tasks · they start with the lesson` : `Task ${current + 1} of ${count}`
  const source = cardSvg({ isNow, chip: `${c.short} ${periodLabel(l)}`, className: c.short === l.cls ? '' : l.cls, right, rightTone: isAllDone ? 'done' : current < 0 ? 'dim' : 'plain', accent: c.colour, rows })
  const next = current < 0 ? 0 : current + 1
  const buttons = [
    ...(current >= 0 && !isAllDone ? [<Button key={`finish-${current}`} label={`✓ End ${labelOf(run.tasks[current]!)}`} onPress={() => void finishTask($, l, run)} />] : []),
    ...(!isAllDone && next < count ? [<Button key={`start-${next}`} label={`▶ Start ${labelOf(run.tasks[next]!)} now`} onPress={() => void jumpTo($, l, run, next)} />] : []),
  ]
  live = null

  return (
    <Box flexDirection="column">
      <Svg source={source} alt={`${l.cls} ${periodLabel(l)}: ${right}`} isInteractive />
      {buttons.length > 0 ? <Box flexDirection="row">{buttons}</Box> : null}
    </Box>
  )
}

// The play on screen for this lesson, if the teacher has jumped or ended a task in it: a copy of the play atom, read by
// each drawing before it builds its rows, since the row builder is not async.
let playCopy: Play | null = null

function playNow(l: Lesson, run: LessonRun): Play | null {
  return playCopy && playCopy.key === lessonKey(l) && playCopy.task < run.tasks.length ? playCopy : null
}

// ▶: this task starts now, any before it are done, and the rest follow on from it.
async function jumpTo($: EngineInterface, l: Lesson, run: LessonRun, i: number) {
  const play: Play = { key: lessonKey(l), task: i, at: await $.clock.now() }
  await setPlay($, play)
  await announce($, `${play.key}|jump${i}|${Math.round(play.at / 1000)}`, spokenLine(i, run.tasks[i]!))
}

// ✓: the running task ends now and the next starts; the last one ending ends the lesson's tasks.
async function finishTask($: EngineInterface, l: Lesson, run: LessonRun) {
  const now = await $.clock.now()
  const { current, slot } = paceOf(l, run, now)
  if (current < 0 || current >= run.tasks.length || !slot) return
  const key = lessonKey(l)
  if (current + 1 < run.tasks.length) {
    await setPlay($, { key, task: current + 1, at: now })
    await announce($, `${key}|jump${current + 1}|${Math.round(now / 1000)}`, spokenLine(current + 1, run.tasks[current + 1]!))
  } else {
    // The last task's bar fills now: it starts where it started and ends here.
    const play = playNow(l, run) ?? { key, task: 0, at: msOf(l.date, l.start) }
    const ends = slots(run, play.task, play.at, play.endedAt)
    const started = ends.find(s => s.i === current)?.from ?? slot.from
    await setPlay($, { key, task: current, at: started, endedAt: now })
    await announce($, `${key}|end|${Math.round(now / 1000)}`, ALL_DONE)
  }
}

async function setPlay($: EngineInterface, play: Play) {
  playCopy = play
  live = null
  await update($, playAtom, () => play)
}

// Ticks on a bar: a mark each for a quiz or question, else a minute each; past 30, a tick every five.
function ticksOf(k: RunTask): number {
  const n = k.marks ?? k.minutes

  return n > 30 ? Math.ceil(n / 5) : Math.max(1, n)
}

// A title for its row: whole words up to 28 characters, never cut mid-word and never with "…".
function shortTitle(title: string): string {
  const words = plain(title).split(' ')
  let out = ''
  for (const w of words) {
    const next = out ? `${out} ${w}` : w
    if (next.length > TITLE_MAX) break
    out = next
  }

  return out || plain(title).slice(0, TITLE_MAX)
}

function hex(n: number): string {
  return `#${n.toString(16).padStart(6, '0')}`
}

// One class as a chip: its short name and period on its colour, black ink, readable on a white terminal.
function chip(ui: T, l: Lesson, key: string) {
  const { Text } = ui
  const c = classOf(l.cls)

  return [<Text key={`${key}-chip`} backgroundColor={c.colour} color="black" bold>{` ${c.short} ${periodLabel(l)} `}</Text>]
}

// The line when there is no card: where the day stands, by class and period, never by the clock.
function stripLine($: EngineInterface, ui: T, s: Strip, now: Date) {
  const { Button, Text } = ui
  const gap = (key: string) => <Text key={key}>{'   '}</Text>
  const then = (rest: Lesson[]) =>
    rest.length === 0
      ? []
      : [<Text key="then" dimColor>{'   then '}</Text>, ...rest.flatMap((l, i) => [...(i > 0 ? [<Text key={`sep${i}`}> </Text>] : []), ...chip(ui, l, `r${i}`)])]
  const nextDay = (l: Lesson | undefined, lastDate: string | undefined, lead: string) =>
    l
      ? [<Text key="lead" dimColor>{`${lead}${dayLabel(l.date, now)} `}</Text>, ...chip(ui, l, 'a')]
      : [<Text key="lead" dimColor wrap="wrap">{`${lead}nothing in the term dates${lastDate ? ` after ${longDay(lastDate)}` : ''}: add the next term to the timetable`}</Text>]
  const plan = (l: Lesson) => [gap('gap'), <Button key="plan" plain dimColor label="what's planned?" onPress={() => void askPlan($, l)} />]

  if (s.kind === 'now') {
    return [<Text key="state" color={classOf(s.lesson.cls).colour} bold>{'● Now '}</Text>, ...chip(ui, s.lesson, 'n'), ...then(s.rest), ...(s.after ? nextDay(s.after, undefined, '   next ') : [])]
  }
  if (s.kind === 'next') {
    return [<Text key="state" color={s.inMs <= SOON_MS ? AMBER : QUIET} bold>{'○ Next '}</Text>, ...chip(ui, s.lesson, 'n'), ...then(s.rest), ...plan(s.lesson)]
  }
  if (s.kind === 'later') {
    return [<Text key="state" color={QUIET} bold>{s.hadLessons ? '✓ Done for today' : '○ No lessons today'}</Text>, ...nextDay(s.after, s.lastDate, '   next '), ...(s.after ? plan(s.after) : [])]
  }
  if (s.kind === 'break') {
    return [<Text key="state" color={QUIET} bold>{`☾ ${s.what}`}</Text>, ...nextDay(s.after, s.lastDate, '   back '), ...(s.after ? plan(s.after) : [])]
  }

  return [
    <Text key="state" dimColor wrap="wrap">
      {`Today is past the term dates in your timetable${s.lastDate ? ` (they end ${longDay(s.lastDate)})` : ''}: add the next term to its Term dates table.`}
    </Text>,
  ]
}

// The day as a tab: each lesson with its time, its class on its colour, and its run sheet's tasks as chips
// (done green, the running one on the class colour, the rest grey). After the last lesson, or on a day without
// any, it shows the next day that has lessons.
async function todayPane($: EngineInterface, ui: T) {
  const { Box, Button, Text } = ui
  await read($, minute)
  await read($, beat)
  playCopy = await read($, playAtom)
  const t = await read($, timetable)
  if (!t) {
    return (
      <Box borderStyle="round" borderColor="gray" paddingX={1}>
        <Text dimColor wrap="wrap">{(await read($, problem)) || 'Reading the timetable…'}</Text>
      </Box>
    )
  }
  const now = new Date(await $.clock.now())
  const ms = now.getTime()
  const today = lessonsOn(t, now)
  const last = today[today.length - 1]
  const isOver = !last || ms >= msOf(last.date, last.end)
  const ahead = isOver ? firstAfter(t, now).lesson : undefined
  const lessons = ahead ? lessonsOn(t, dateFrom(ahead.date)) : today
  const dayName = ahead ? `${dayLabel(ahead.date, now) === 'tomorrow' ? 'Tomorrow' : 'Next'}, ${longDay(ahead.date)}` : `Today, ${longDay(isoOf(now))}`
  const runs = await read($, runsAtom)

  const block = (l: Lesson, i: number) => {
    const from = msOf(l.date, l.start)
    const to = msOf(l.date, l.end)
    const state = ms >= to ? '✓' : ms >= from ? '●' : '○'
    const run = runFor(runs, l)
    const current = run ? paceOf(l, run, ms).current : -1

    return (
      <Box key={`lesson-${i}`} flexDirection="column" marginTop={1}>
        <Box flexDirection="row" flexWrap="wrap">
          <Text color={state === '●' ? classOf(l.cls).colour : QUIET} bold>{`${state} `}</Text>
          <Text dimColor>{`${l.start} to ${l.end}  `}</Text>
          {chip(ui, l, `c${i}`)}
          {classOf(l.cls).short === l.cls ? null : <Text bold>{`  ${l.cls}`}</Text>}
        </Box>
        {run ? (
          <Box flexDirection="row" flexWrap="wrap" paddingLeft={2}>
            {run.tasks.map((k, j) => (
              <Box key={`t${i}-${j}`} marginRight={1}>
                <Text backgroundColor={j < current ? DONE_BG : j === current ? classOf(l.cls).colour : AHEAD_BG} color="black">
                  {` ${j < current ? '✓ ' : ''}${j + 1} ${plain(k.title)} · ${k.marks ? `${k.marks} marks` : `${k.minutes} min`} `}
                </Text>
              </Box>
            ))}
          </Box>
        ) : (
          <Box flexDirection="row" flexWrap="wrap" paddingLeft={2}>
            <Text dimColor>No run sheet handed over yet  </Text>
            <Button key={`plan-${i}`} plain dimColor label="what's planned?" onPress={() => void askPlan($, l)} />
          </Box>
        )}
      </Box>
    )
  }

  return (
    <Box flexDirection="column" borderStyle="round" borderColor="gray" paddingX={1}>
      <Box flexDirection="row" justifyContent="space-between">
        <Text bold><Text color="#5FB37A">◆</Text>{` ${dayName}`}</Text>
        <Text dimColor>{clockOf(ms)}</Text>
      </Box>
      {lessons.length === 0 ? <Text dimColor wrap="wrap">{describeDay(t, now)}</Text> : lessons.map(block)}
    </Box>
  )
}

// /lessons try: a pretend Lower Sixth lesson starting now: a five-mark quiz, a listening task and the Hall,
// a minute each, running one after another so the teacher can watch and hear it move on.
async function startTrial($: EngineInterface): Promise<{ lesson: Lesson; run: LessonRun }> {
  const now = await $.clock.now()
  const date = isoOf(new Date(now))
  const lesson: Lesson = { cls: 'Lower Sixth', from: 7, to: 7, start: clockOf(now), end: clockOf(now + 20 * 60000), date }
  const run: LessonRun = {
    cls: lesson.cls,
    date,
    period: periodLabel(lesson),
    tasks: [
      { title: 'Quiz: Signals and connectors', label: 'Quiz', marks: 5, minutes: 1, detail: 'Five marks, unannounced.' },
      { title: 'Era 1 from the front', label: 'Listen', minutes: 1, detail: 'Each pupil listens and writes; no calling out.' },
      { title: 'Set Hall 1', label: 'Hall', minutes: 1, detail: 'Each opens their own worksheet.' },
    ],
    savedAt: now,
  }
  await update($, trialAtom, () => ({ lesson, run }))
  await setPlay($, { key: lessonKey(lesson), task: 0, at: now })
  if ((await soundOf($)) === 'voice') void prepareVoice($, run)
  await announce($, `${lessonKey(lesson)}|try|${Math.round(now / 1000)}`, spokenLine(0, run.tasks[0]!))

  return { lesson, run }
}

// The words go in the prompt box for the teacher to check and send.
async function askPlan($: EngineInterface, l: Lesson) {
  const filled = await $.prompt.fill({ text: `What's planned for ${l.cls}, ${longDay(l.date)} ${periodLabel(l)}?`, mode: 'replace' })
  $.ui.toast(filled.isFilled ? 'In your prompt: check it and press Enter' : 'Could not reach your prompt box')
}

// A class's chip: the short name and colour above where it has one, else its own name and a colour from the same
// set, the same class always the same colour.
const PALETTE = ['#8AA4E8', '#7FC8C8', '#A78BFA', '#9FD18B', '#E8C66A', '#E8A0C0']

function classOf(cls: string): { short: string; colour: string } {
  const known = CLASSES[cls.trim().toLowerCase()]
  if (known) return known
  let h = 0
  for (const ch of cls) h = (h * 31 + ch.charCodeAt(0)) >>> 0

  return { short: cls.trim(), colour: PALETTE[h % PALETTE.length]! }
}

// A title without the plan's markdown, as it reads on a chip or aloud.
function plain(text: string): string {
  return text.replace(/[*_`]/g, '').replace(/\s+/g, ' ').trim()
}

function clockOf(ms: number): string {
  const d = new Date(ms)

  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

// "", "today", "tomorrow", or a weekday: the next such day after today (/lessons alone is today).
function dayAsked(arg: string, now: Date): Date | undefined {
  if (arg === '' || arg === 'today') return now
  if (arg === 'tomorrow') return addDays(now, 1)
  const i = DAYS.findIndex(d => arg.startsWith(d.toLowerCase()))
  if (i < 0) return undefined

  return addDays(now, (i - now.getDay() + 7) % 7 || 7)
}

