// The lesson card, painted cell by cell for a Raster so it looks the same on a white terminal as on a
// dark one: a dark card, a header line, and a row a task with a rounded track, a dotted
// fill shading up to the task's colour, a tick a mark (or a minute), a rounded chip riding at the head of the
// fill, and the percentage on the right. Pure: the same inputs paint the same cells, so tests can read them.

export const DEFAULT = 0x01000000 // the terminal's own colour, outside the card
export const CARD = 0x1d1d21
export const TRACK = 0x41414a // clearly lighter than the card, so the empty bar reads
export const TEXT = 0xececec
export const DIM = 0x8e8e96
export const GREEN = 0x5fbf7f
export const GREY_PILL = 0x4a4a52
const TICK = 0x74747e
const BLACK = 0x000000
const WHITE = 0xffffff

export type Seg = { text: string; fg?: number; bg?: number }

// One row of cells: [codePoint, foreground, background] each, packed as the Raster wants them.
class Row {
  readonly words: Uint32Array

  constructor(readonly width: number, bg: number) {
    this.words = new Uint32Array(width * 3)
    for (let c = 0; c < width; c += 1) this.set(c, ' ', TEXT, bg)
  }

  set(c: number, ch: string, fg: number, bg?: number) {
    if (c < 0 || c >= this.width) return
    this.words[c * 3] = ch.codePointAt(0) ?? 32
    this.words[c * 3 + 1] = fg
    if (bg !== undefined) this.words[c * 3 + 2] = bg
  }

  bgAt(c: number): number {
    return this.words[c * 3 + 2] ?? CARD
  }

  // Words from column c, cut at the row's end (titles are kept short where they are made, so nothing is cut here).
  text(c: number, s: string, fg: number, bg?: number): number {
    let at = c
    for (const ch of s) this.set(at++, ch, fg, bg)

    return at
  }

  encode(): string {
    return base64(new Uint8Array(this.words.buffer))
  }
}

// The header: segments from the left, segments flush right, on the card.
export function header(width: number, left: Seg[], right: Seg[]): string {
  const row = new Row(width, CARD)
  // Column 1, the same as each task's dot below it, so the dots stand in one line.
  let at = 1
  for (const s of left) at = row.text(at, s.text, s.fg ?? TEXT, s.bg ?? CARD)
  const rightLength = right.reduce((n, s) => n + [...s.text].length, 0)
  at = Math.max(at + 2, width - 1 - rightLength)
  for (const s of right) at = row.text(at, s.text, s.fg ?? TEXT, s.bg ?? CARD)

  return row.encode()
}

export type TaskLook = {
  width: number
  glyph: string
  glyphFg: number
  title: string
  titleWidth: number
  // How far through, 0 to 1.
  fraction: number
  // Tick marks: one a mark, else one a minute.
  ticks: number
  pill: string
  pillBg: number
  pillFg: number
  // The task's colour: the fill shades up to it.
  accent: number
  percent: string
  // The shimmer's place, moving on each frame.
  phase: number
}

// One task's row: glyph, title, the track with its fill, ticks and chip, then the percentage.
export function task(look: TaskLook): string {
  const { width } = look
  const row = new Row(width, CARD)
  row.set(1, look.glyph, look.glyphFg)
  row.text(3, look.title, TEXT)
  const start = 3 + look.titleWidth + 2
  const end = width - 6 // the bar's last column + 1; five columns of percentage after
  const inner = end - start - 2
  if (inner < 4) return row.encode()
  row.set(start, '◖', TRACK, CARD)
  row.set(end - 1, '◗', TRACK, CARD)
  for (let c = start + 1; c < end - 1; c += 1) row.set(c, ' ', TEXT, TRACK)
  const head = start + 1 + Math.round(Math.max(0, Math.min(1, look.fraction)) * inner)
  const span = Math.max(1, head - start - 1)
  const shine = start + 1 + ((look.phase % (span + 12)) - 6)
  for (let c = start + 1; c < head; c += 1) {
    const t = (c - start) / span
    const lit = Math.abs(c - shine) <= 2 ? 0.35 : 0
    row.set(c, dots(c, t), mix(mix(TRACK, look.accent, 0.55 + 0.45 * t), WHITE, lit), TRACK)
  }
  for (let k = 1; k < look.ticks; k += 1) {
    const c = start + 1 + Math.round((k / look.ticks) * inner)
    if (c > start && c < end - 1) row.set(c, '│', c < head ? mix(look.accent, WHITE, 0.25) : TICK, TRACK)
  }
  // The chip rides with its right end at the head of the fill, kept inside the track.
  const label = ` ${look.pill} `
  const width0 = [...label].length + 2
  const at = Math.max(start, Math.min(end - width0, head - width0 + 1))
  row.set(at, '◖', look.pillBg, row.bgAt(at) === CARD ? CARD : TRACK)
  row.text(at + 1, label, look.pillFg, look.pillBg)
  row.set(at + width0 - 1, '◗', look.pillBg, row.bgAt(at + width0 - 1) === CARD ? CARD : TRACK)
  const pct = look.percent.padStart(4)
  row.text(width - 5, pct, DIM)

  return row.encode()
}

// A braille cell of dots, denser toward the head: the same column always the same pattern, so only the shine moves.
function dots(c: number, t: number): string {
  let h = Math.imul(c + 1, 2654435761) >>> 0
  const threshold = 2 + Math.round(t * 5)
  let bits = 0
  for (let d = 0; d < 8; d += 1) {
    if ((h & 7) < threshold) bits |= 1 << d
    h >>>= 3
    if (h === 0) h = Math.imul(c + d + 7, 40503) >>> 0
  }

  return String.fromCodePoint(0x2800 + (bits || 0x40))
}

// Two colours mixed: `amount` of the way from a to b.
export function mix(a: number, b: number, amount: number): number {
  const ch = (shift: number) => {
    const x = (a >> shift) & 255
    const y = (b >> shift) & 255

    return Math.round(x + (y - x) * amount) << shift
  }

  return ch(16) | ch(8) | ch(0)
}

export function hexOf(colour: string): number {
  return parseInt(colour.replace('#', ''), 16)
}

// What a painted row says, for tests: its characters in order.
export function textOf(cells: string): string {
  const bytes = unbase64(cells)
  const words = new Uint32Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 4)
  let out = ''
  for (let i = 0; i < words.length; i += 3) out += String.fromCodePoint(words[i]!)

  return out
}

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

function base64(bytes: Uint8Array): string {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i]! << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0)
    out += ALPHABET[(n >> 18) & 63]! + ALPHABET[(n >> 12) & 63]!
    out += i + 1 < bytes.length ? ALPHABET[(n >> 6) & 63]! : '='
    out += i + 2 < bytes.length ? ALPHABET[n & 63]! : '='
  }

  return out
}

function unbase64(text: string): Uint8Array {
  const clean = text.replace(/=+$/, '')
  const out = new Uint8Array(Math.floor((clean.length * 3) / 4))
  let n = 0
  let bits = 0
  let o = 0
  for (const ch of clean) {
    n = (n << 6) | ALPHABET.indexOf(ch)
    bits += 6
    if (bits >= 8) {
      bits -= 8
      out[o++] = (n >> bits) & 255
    }
  }

  return out
}

files.hooks/run.ts:
// A lesson's run sheet: which lesson it belongs to, and the run tool's input checked against the timetable.
// Pure, like timetable.ts.

import type { Lesson, LessonRun, Timetable } from '../types'
import { dateFrom, dateOf, isoOf, lessonsOn, periodLabel } from './timetable'

export function keyOf(cls: string, date: string, period: string): string {
  return `${cls.trim().toLowerCase()}|${date}|${period.trim().toUpperCase()}`
}

export function lessonKey(l: Lesson): string {
  return keyOf(l.cls, l.date, periodLabel(l))
}

export function runFor(runs: readonly LessonRun[], l: Lesson): LessonRun | undefined {
  return runs.find(r => keyOf(r.cls, r.date, r.period) === lessonKey(l))
}

// A run as a planning window hands it over, checked against the timetable: the lesson must be on it.
export function asRun(input: Record<string, unknown>, t: Timetable, now: Date): { run?: LessonRun; why?: string } {
  const text = (v: unknown) => (typeof v === 'string' ? v.trim() : '')
  const cls = text(input.class)
  const period = text(input.period).toUpperCase().replace(/\s+/g, '')
  const date = dateIn(text(input.date), now)
  if (!cls || !period || !date) return { why: 'Give class (as the timetable names it, e.g. "Lower Sixth"), date ("2026-11-02" or "Mon 2 Nov"), period ("P7" or "P4+P5") and tasks.' }
  const day = lessonsOn(t, dateFrom(date))
  const lesson = day.find(l => keyOf(l.cls, l.date, periodLabel(l)) === keyOf(cls, date, period))
  if (!lesson) {
    const has = day.map(l => `${l.cls} ${periodLabel(l)}`).join(', ') || 'no lessons'
    return { why: `${cls} ${period} is not on the timetable for ${date}: that day has ${has}.` }
  }
  const tasks = (Array.isArray(input.tasks) ? (input.tasks as Record<string, unknown>[]) : [])
    .map(k => {
      const number = (v: unknown) => (typeof v === 'number' ? Math.round(v) : Number(text(v)) || 0)
      const marks = number(k.marks) || undefined
      const title = text(k.title)

      return {
        title,
        // One mark, one minute (a common rule for papers and quizzes) when the plan gives marks and no minutes.
        minutes: number(k.minutes) || marks || 0,
        label: text(k.label).split(/\s+/)[0] || title.split(/[\s/]+/)[0] || 'Task',
        marks,
        start: /^\d{1,2}:\d{2}$/.test(text(k.start)) ? text(k.start).padStart(5, '0') : undefined,
        detail: text(k.detail) || undefined,
      }
    })
    .filter(k => k.title && k.minutes > 0)
    .slice(0, 12)
  if (tasks.length === 0) return { why: 'Give tasks: [{ title, minutes or marks, label?, start?, detail? }], in order.' }

  return { run: { cls: lesson.cls, date, period: periodLabel(lesson), tasks, savedAt: now.getTime() } }
}

// "2026-11-02", or "Mon 2 Nov" / "2 November" in the year that makes it nearest to now.
function dateIn(text: string, now: Date): string | undefined {
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text
  if (/\d{4}/.test(text)) return dateOf(text)
  const guesses = [now.getFullYear() - 1, now.getFullYear(), now.getFullYear() + 1].flatMap(y => dateOf(`${text} ${y}`) ?? [])
  const near = (iso: string) => Math.abs(dateFrom(iso).getTime() - dateFrom(isoOf(now)).getTime())

  return guesses.sort((x, y) => near(x) - near(y))[0]
}

// When each task runs: the task the lesson started from (the first, at the bell, or the one the teacher jumped to)
// and every task after it following on as the one before runs out. Tasks before it are done.
export type Slot = { i: number; from: number; to: number }

export function slots(run: LessonRun, from: number, at: number, endedAt?: number): Slot[] {
  const out: Slot[] = []
  let t = at
  for (let i = from; i < run.tasks.length; i += 1) {
    const to = i === from && endedAt !== undefined ? endedAt : t + run.tasks[i]!.minutes * 60000
    out.push({ i, from: t, to })
    t = to
  }

  return out
}

// Where the lesson is: the task running and how far through it, -1 before the first starts, past the last
// (tasks.length) once every task is done.
export function paceAt(run: LessonRun, all: readonly Slot[], from: number, now: number): { current: number; slot?: Slot; fraction: number } {
  const first = all[0]
  if (!first || now < first.from) return { current: first ? from - 1 : run.tasks.length, fraction: 0 }
  const slot = all.find(s => now >= s.from && now < s.to)
  if (!slot) return { current: run.tasks.length, fraction: 1 }

  return { current: slot.i, slot, fraction: (now - slot.from) / Math.max(1, slot.to - slot.from) }
}

files.hooks/svg.ts:
// The lesson card as a picture, for the Claude desktop app (and the phone), which draw a mod's SVG: the look of
// the desktop app's own panels. A dark rounded card; a row a task with a rounded track, a dotted fill shading up
// to the task's colour, tick marks, a rounded chip riding at the head of the fill, and the percentage. The SVG
// moves by itself (SMIL): the fill and chip slide to the end of the task's time, the count and percentage step
// on, and a shine runs along the fill. Pure: tests read the markup.

export type SvgRow = {
  state: 'done' | 'running' | 'waiting'
  title: string
  label: string
  ticks: number
  // How far through when drawn, 0 to 1, and how many seconds are left of it (running only).
  fraction: number
  secondsLeft: number
}

export type SvgCard = {
  isNow: boolean
  chip: string
  className: string
  right: string
  rightTone: 'done' | 'plain' | 'dim'
  accent: string
  rows: SvgRow[]
}

const W = 760
const PAD = 16
const HEAD = 40
const ROW = 44
const TRACK_X = 300
const TRACK_END = W - 96
const TRACK_W = TRACK_END - TRACK_X
const TRACK_H = 26
const CARD = '#1c1c1f'
const TRACK = '#2c2c31'
const TEXT = '#ececec'
const DIM = '#8e8e96'
const GREEN = '#5fbf7f'
const GREY = '#4a4a52'
const FONT = '-apple-system, BlinkMacSystemFont, "SF Pro Text", "Helvetica Neue", sans-serif'

export function cardHeight(rows: number): number {
  return PAD + HEAD + rows * ROW + 10
}

export function cardSvg(card: SvgCard): string {
  const h = cardHeight(card.rows.length)
  const parts: string[] = []
  parts.push(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${h}" viewBox="0 0 ${W} ${h}" font-family='${FONT}'>`)
  parts.push(defs(card))
  parts.push(`<rect x="0.5" y="0.5" width="${W - 1}" height="${h - 1}" rx="16" fill="${CARD}" stroke="#2a2a2f"/>`)
  parts.push(header(card))
  card.rows.forEach((row, i) => parts.push(rowSvg(card, row, i)))
  parts.push('</svg>')

  return parts.join('')
}

// The dotted texture: a tile of squares of differing brightness, the same every time; and the shine.
function defs(card: SvgCard): string {
  const dots: string[] = []
  let seed = 7
  const random = () => {
    seed = (Math.imul(seed, 1103515245) + 12345) >>> 0

    return (seed >>> 8) / 16777216
  }
  for (let y = 0; y < 24; y += 3) {
    for (let x = 0; x < 48; x += 3) {
      const o = random()
      if (o > 0.3) dots.push(`<rect x="${x}" y="${y}" width="2" height="2" fill="${card.accent}" opacity="${(0.25 + o * 0.75).toFixed(2)}"/>`)
    }
  }

  return [
    '<defs>',
    `<pattern id="dots" width="48" height="24" patternUnits="userSpaceOnUse">${dots.join('')}</pattern>`,
    `<pattern id="dotsDone" width="48" height="24" patternUnits="userSpaceOnUse">${dots.join('').replaceAll(card.accent, GREEN)}</pattern>`,
    '<linearGradient id="fade" x1="0" x2="1" y1="0" y2="0"><stop offset="0" stop-color="#fff" stop-opacity="0.25"/><stop offset="1" stop-color="#fff" stop-opacity="1"/></linearGradient>',
    '<mask id="fadeMask" maskContentUnits="objectBoundingBox"><rect width="1" height="1" fill="url(#fade)"/></mask>',
    '<linearGradient id="shine" x1="0" x2="1" y1="0" y2="0"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset="0.5" stop-color="#fff" stop-opacity="0.35"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>',
    '</defs>',
  ].join('')
}

function header(card: SvgCard): string {
  const y = PAD + HEAD / 2
  const chipW = textWidth(card.chip, 13) + 20
  const tone = card.rightTone === 'done' ? GREEN : card.rightTone === 'dim' ? DIM : TEXT

  return [
    `<circle cx="24" cy="${y}" r="4.5" fill="${card.isNow ? card.accent : DIM}"/>`,
    `<text x="38" y="${y + 5}" font-size="15" font-weight="600" fill="${card.isNow ? card.accent : DIM}">${card.isNow ? 'Now' : 'Next'}</text>`,
    `<rect x="86" y="${y - 12}" width="${chipW}" height="24" rx="12" fill="${card.accent}"/>`,
    `<text x="${86 + chipW / 2}" y="${y + 5}" font-size="13" font-weight="700" fill="#000" text-anchor="middle">${esc(card.chip)}</text>`,
    `<text x="${86 + chipW + 12}" y="${y + 5}" font-size="15" fill="${TEXT}">${esc(card.className)}</text>`,
    `<text x="${W - 24}" y="${y + 5}" font-size="14" fill="${tone}" text-anchor="end">${esc(card.right)}</text>`,
  ].join('')
}

function rowSvg(card: SvgCard, row: SvgRow, i: number): string {
  const cy = PAD + HEAD + i * ROW + ROW / 2
  const ty = cy - TRACK_H / 2
  const isDone = row.state === 'done'
  const isRunning = row.state === 'running'
  const f = isDone ? 1 : isRunning ? Math.max(0, Math.min(1, row.fraction)) : 0
  const dur = isRunning ? Math.max(0.1, row.secondsLeft) : 0
  const fillW = TRACK_W * f
  const out: string[] = []
  // The dot, then the title.
  out.push(
    isDone
      ? `<text x="19" y="${cy + 5}" font-size="15" fill="${GREEN}">✓</text>`
      : isRunning
        ? `<circle cx="24" cy="${cy}" r="4.5" fill="${card.accent}"/>`
        : `<circle cx="24" cy="${cy}" r="4" fill="none" stroke="${DIM}" stroke-width="1.5"/>`,
  )
  out.push(`<text x="38" y="${cy + 5}" font-size="15" fill="${TEXT}">${esc(row.title)}</text>`)
  // The track.
  out.push(`<rect x="${TRACK_X}" y="${ty}" width="${TRACK_W}" height="${TRACK_H}" rx="${TRACK_H / 2}" fill="${TRACK}"/>`)
  // The fill: a tint and dots fading in from the left and brightest at the head, growing to the end of the
  // task's time, inside the track's rounded shape; a shine runs along it while the task runs.
  const clip = `track${i}`
  const grow = isRunning ? `<animate attributeName="width" from="${fillW}" to="${TRACK_W}" dur="${dur}s" fill="freeze"/>` : ''
  out.push(`<clipPath id="${clip}"><rect x="${TRACK_X}" y="${ty}" width="${TRACK_W}" height="${TRACK_H}" rx="${TRACK_H / 2}"/></clipPath>`)
  if (f > 0 || isRunning) {
    const colour = isDone ? GREEN : card.accent
    out.push(
      `<g clip-path="url(#${clip})">`,
      `<rect x="${TRACK_X}" y="${ty}" width="${fillW}" height="${TRACK_H}" fill="${colour}" opacity="0.22" mask="url(#fadeMask)">${grow}</rect>`,
      `<rect x="${TRACK_X}" y="${ty}" width="${fillW}" height="${TRACK_H}" fill="url(#${isDone ? 'dotsDone' : 'dots'})" mask="url(#fadeMask)">${grow}</rect>`,
    )
    if (isRunning) {
      out.push(
        `<clipPath id="grow${i}"><rect x="${TRACK_X}" y="${ty}" width="${fillW}" height="${TRACK_H}">${grow}</rect></clipPath>`,
        `<g clip-path="url(#grow${i})"><rect x="${TRACK_X - 80}" y="${ty}" width="80" height="${TRACK_H}" fill="url(#shine)"><animate attributeName="x" from="${TRACK_X - 80}" to="${TRACK_END}" dur="2.6s" repeatCount="indefinite"/></rect></g>`,
      )
    }
    out.push('</g>')
  }
  // A tick a mark (or a minute), lighter over the fill.
  for (let k = 1; k < row.ticks; k += 1) {
    const x = TRACK_X + (k / row.ticks) * TRACK_W
    out.push(`<line x1="${x}" x2="${x}" y1="${cy - 6}" y2="${cy + 6}" stroke="${x <= TRACK_X + fillW ? 'rgba(255,255,255,0.55)' : '#4a4a52'}" stroke-width="1.5" stroke-linecap="round"/>`)
  }
  // The chip, riding with its right end at the head of the fill; its count stepping on with the ticks.
  const labels = isDone
    ? [{ text: `✓ ${row.label} ${row.ticks}/${row.ticks}`, from: 0, to: Infinity }]
    : isRunning
      ? steps(row.ticks, f, dur).map(s => ({ text: `${row.label} ${s.value}/${row.ticks}`, from: s.from, to: s.to }))
      : [{ text: `${row.label} 0/${row.ticks}`, from: 0, to: Infinity }]
  const chipW = Math.max(...labels.map(l => textWidth(l.text, 13))) + 26
  const chipFill = isDone ? GREEN : isRunning ? card.accent : GREY
  const chipInk = isDone || isRunning ? '#000' : TEXT
  const x0 = Math.max(TRACK_X, Math.min(TRACK_END - chipW, TRACK_X + fillW - chipW))
  const x1 = TRACK_END - chipW
  const slide = isRunning ? `<animateTransform attributeName="transform" type="translate" from="0 0" to="${x1 - x0} 0" dur="${dur}s" fill="freeze"/>` : ''
  out.push(`<g>${slide}<rect x="${x0}" y="${ty}" width="${chipW}" height="${TRACK_H}" rx="${TRACK_H / 2}" fill="${chipFill}"/>`)
  for (const l of labels) out.push(timed(`<text x="${x0 + chipW / 2}" y="${cy + 5}" font-size="13" font-weight="700" fill="${chipInk}" text-anchor="middle">${esc(l.text)}`, l.from, l.to))
  out.push('</g>')
  // The percentage, stepping on a per cent at a time.
  const pcts = isRunning ? steps(100, f, dur).map(s => ({ text: `${s.value}%`, from: s.from, to: s.to })) : [{ text: isDone ? '100%' : '0%', from: 0, to: Infinity }]
  for (const p of pcts) out.push(timed(`<text x="${W - 24}" y="${cy + 5}" font-size="14" fill="${DIM}" text-anchor="end">${p.text}`, p.from, p.to))

  return out.join('')
}

// The values a count passes through from where it is to its end, each with when (seconds from now) it shows.
function steps(of: number, f: number, dur: number): { value: number; from: number; to: number }[] {
  const now = Math.min(of, Math.floor(f * of))
  const at = (v: number) => (f >= 1 ? 0 : Math.max(0, ((v / of - f) / (1 - f)) * dur))
  const out: { value: number; from: number; to: number }[] = []
  for (let v = now; v <= of; v += 1) out.push({ value: v, from: v === now ? 0 : at(v), to: v === of ? Infinity : at(v + 1) })

  return out
}

// A text shown from one moment to another: hidden until it starts (unless it is the one showing now).
function timed(open: string, from: number, to: number): string {
  const show = from > 0 ? `<set attributeName="visibility" to="visible" begin="${from.toFixed(2)}s"/>` : ''
  const hide = Number.isFinite(to) ? `<set attributeName="visibility" to="hidden" begin="${to.toFixed(2)}s"/>` : ''
  const start = from > 0 ? open.replace('<text ', '<text visibility="hidden" ') : open

  return `${start}${show}${hide}</text>`
}

// Close enough for laying out a chip: the system font's average width at a size.
function textWidth(text: string, size: number): number {
  return [...text].length * size * 0.6
}

function esc(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

files.hooks/timetable.ts:
// The timetable file read into the shape the strip needs, and the day worked out from it.
// Pure: no engine calls, so the tests can check any day and time.

import type { Lesson, Period, Timetable } from '../types'

export const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'] as const
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const LOOK_AHEAD_DAYS = 60

// What the strip says at one moment: the lesson it is about, and what follows it.
export type Strip =
  | { kind: 'now'; lesson: Lesson; leftMs: number; rest: Lesson[]; after?: Lesson }
  | { kind: 'next'; lesson: Lesson; inMs: number; rest: Lesson[] }
  | { kind: 'later'; hadLessons: boolean; after?: Lesson; lastDate?: string }
  | { kind: 'break'; what: string; after?: Lesson; lastDate?: string }
  | { kind: 'unknown'; lastDate?: string }

export function parseTimetable(md: string): Timetable {
  const periods = table(md, 'Periods')
    .slice(1)
    .flatMap(([p = '', time = '']): Period[] => {
      const span = /(\d{1,2}:\d{2}) to (\d{1,2}:\d{2})/.exec(time)
      if (!/^\d+$/.test(p) || !span) return []
      const wed = /Wednesday (\d{1,2}:\d{2})/.exec(time)

      return [{ p: Number(p), start: hhmm(span[1]!), end: hhmm(span[2]!), ...(wed ? { wedStart: hhmm(wed[1]!) } : {}) }]
    })
  const [head = [], ...rows] = table(md, 'Week')
  const week: Record<string, Record<string, string>> = {}
  for (const row of rows) {
    const p = row[0] ?? ''
    if (!/^\d+$/.test(p)) continue
    head.forEach((day, i) => {
      const cls = row[i]
      if (i > 0 && cls) (week[day] ??= {})[p] = cls
    })
  }
  const oneOff = table(md, 'One-off days')
    .slice(1)
    .flatMap(([when = '', runs = '']) => {
      const date = dateOf(when)
      const slots = [...runs.matchAll(/\b(Mon|Tue|Wed|Thu|Fri|Sat) P(\d+)/g)].map(m => ({ day: m[1]!, p: Number(m[2]) }))

      return date && slots.length > 0 ? [{ date, runs: slots }] : []
    })
  const terms = table(md, 'Term dates')
    .slice(1)
    .flatMap(([what = '', from = '', to = '', lessons = '']) => {
      const [a, b] = [dateOf(from), dateOf(to)]

      return what && a && b ? [{ what, from: a, to: b, hasLessons: /^y/i.test(lessons) }] : []
    })

  return { periods, week, oneOff, terms }
}

// The rows of the first table under a `## heading`, each as its cells; the |---| rule left out.
function table(md: string, heading: string): string[][] {
  const lines = md.split('\n')
  const at = lines.findIndex(l => l.trim().toLowerCase() === `## ${heading.toLowerCase()}`)
  if (at < 0) return []
  const rows: string[][] = []
  for (const line of lines.slice(at + 1)) {
    if (line.startsWith('## ')) break
    const t = line.trim()
    if (t.startsWith('|')) rows.push(t.replace(/^\||\|$/g, '').split('|').map(c => c.trim()))
    else if (rows.length > 0) break
  }

  return rows.filter(r => !r.every(c => /^:?-+:?$/.test(c)))
}

// "8 Sep 2026", "Tue 8 Sep 2026", "16 October 2026" as "2026-09-08".
export function dateOf(text: string): string | undefined {
  const m = /(\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]* (\d{4})/.exec(text)

  return m ? isoOf(new Date(Number(m[3]), MONTHS.indexOf(m[2]!), Number(m[1]))) : undefined
}

export function isoOf(d: Date): string {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

// Whether a day has lessons by the term dates: in a term, in a break (named), or past what the table knows.
// With no term dates at all, every day is a teaching day, as the timetable alone would have it.
export function dayKind(t: Timetable, iso: string): { kind: 'term' } | { kind: 'break'; what: string } | { kind: 'unknown' } {
  if (t.terms.length === 0) return { kind: 'term' }
  const covering = t.terms.filter(r => r.from <= iso && iso <= r.to)
  const off = covering.find(r => !r.hasLessons)
  if (off) return { kind: 'break', what: off.what }
  if (covering.length > 0) return { kind: 'term' }
  const first = t.terms.reduce((a, r) => (r.from < a ? r.from : a), t.terms[0]!.from)
  const last = lastDate(t)!

  return iso < first || iso > last ? { kind: 'unknown' } : { kind: 'break', what: 'Holiday' }
}

function lastDate(t: Timetable): string | undefined {
  return t.terms.reduce<string | undefined>((a, r) => (a === undefined || r.to > a ? r.to : a), undefined)
}

// A day's lessons in order, a class running on into the next period joined into one double.
export function lessonsOn(t: Timetable, d: Date): Lesson[] {
  const iso = isoOf(d)
  if (dayKind(t, iso).kind !== 'term') return []
  const day = DAYS[d.getDay()]!
  const special = t.oneOff.find(o => o.date === iso)
  // A rotation day runs the listed slots as P1, P2, ... in that order.
  const slots = special
    ? special.runs.map((r, i) => ({ p: i + 1, cls: t.week[r.day]?.[String(r.p)] }))
    : t.periods.map(per => ({ p: per.p, cls: t.week[day]?.[String(per.p)] }))
  const out: Lesson[] = []
  for (const slot of slots) {
    const period = t.periods.find(x => x.p === slot.p)
    if (!slot.cls || !period) continue
    const last = out[out.length - 1]
    if (last && last.cls === slot.cls && last.to === slot.p - 1) {
      last.to = slot.p
      last.end = period.end
      continue
    }
    const start = day === 'Wed' && period.wedStart ? period.wedStart : period.start
    out.push({ cls: slot.cls, from: slot.p, to: slot.p, start, end: period.end, date: iso })
  }

  return out
}

// The first lesson from the day after `d`, or the last date the term dates know when they run out first.
export function firstAfter(t: Timetable, d: Date): { lesson?: Lesson; lastDate?: string } {
  for (let i = 1; i <= LOOK_AHEAD_DAYS; i += 1) {
    const day = addDays(d, i)
    if (dayKind(t, isoOf(day)).kind === 'unknown') return { lastDate: lastDate(t) }
    const lessons = lessonsOn(t, day)
    if (lessons.length > 0) return { lesson: lessons[0] }
  }

  return {}
}

export function stripAt(t: Timetable, now: Date): Strip {
  const kind = dayKind(t, isoOf(now))
  if (kind.kind === 'unknown') return { kind: 'unknown', lastDate: lastDate(t) }
  const ahead = firstAfter(t, now)
  if (kind.kind === 'break') return { kind: 'break', what: kind.what, after: ahead.lesson, lastDate: ahead.lastDate }
  const today = lessonsOn(t, now)
  const ms = now.getTime()
  const current = today.find(l => msOf(l.date, l.start) <= ms && ms < msOf(l.date, l.end))
  if (current) {
    const rest = today.slice(today.indexOf(current) + 1)

    return { kind: 'now', lesson: current, leftMs: msOf(current.date, current.end) - ms, rest, after: rest.length === 0 ? ahead.lesson : undefined }
  }
  const coming = today.filter(l => msOf(l.date, l.start) > ms)
  if (coming.length > 0) return { kind: 'next', lesson: coming[0]!, inMs: msOf(coming[0]!.date, coming[0]!.start) - ms, rest: coming.slice(1) }

  return { kind: 'later', hadLessons: today.length > 0, after: ahead.lesson, lastDate: ahead.lastDate }
}

// A day's lessons in a sentence, for /lessons.
export function describeDay(t: Timetable, d: Date): string {
  const iso = isoOf(d)
  const kind = dayKind(t, iso)
  const name = longDay(iso)
  if (kind.kind === 'unknown') return `${name} is past the term dates in your timetable: add the next term to its Term dates table.`
  if (kind.kind === 'break') {
    const { lesson } = firstAfter(t, d)
    if (!lesson) return `${name}: ${kind.what}, no lessons.`
    const back = lessonsOn(t, dateFrom(lesson.date))

    return `${name}: ${kind.what}, no lessons. Back ${longDay(lesson.date)}: ${listOf(back)}.`
  }
  const lessons = lessonsOn(t, d)
  if (lessons.length === 0) return `${name}: no lessons.`
  const isRotation = t.oneOff.some(o => o.date === iso)

  return `${name}${isRotation ? ' (rotation day)' : ''}: ${listOf(lessons)}.`
}

function listOf(lessons: Lesson[]): string {
  return lessons.map(l => `${l.cls} ${periodLabel(l)} ${l.start} to ${l.end}`).join(' · ')
}

export function periodLabel(l: Lesson): string {
  return l.from === l.to ? `P${l.from}` : `P${l.from}+P${l.to}`
}

// "today", "tomorrow", a weekday within the week, else "Mon 2 Nov".
export function dayLabel(iso: string, today: Date): string {
  if (iso === isoOf(today)) return 'today'
  if (iso === isoOf(addDays(today, 1))) return 'tomorrow'
  const days = Math.round((dateFrom(iso).getTime() - dateFrom(isoOf(today)).getTime()) / 86400000)

  return days > 0 && days < 7 ? DAYS[dateFrom(iso).getDay()]! : longDay(iso)
}

export function longDay(iso: string): string {
  const d = dateFrom(iso)

  return `${DAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()]}`
}

// "42 min", "1 h 05", "3 h".
export function duration(ms: number): string {
  const mins = Math.max(1, Math.ceil(ms / 60000))
  if (mins < 60) return `${mins} min`
  const rest = mins % 60

  return rest === 0 ? `${Math.floor(mins / 60)} h` : `${Math.floor(mins / 60)} h ${pad(rest)}`
}

export function addDays(d: Date, n: number): Date {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)
}

export function dateFrom(iso: string): Date {
  const [y, m, d] = iso.split('-').map(Number)

  return new Date(y!, m! - 1, d!)
}

// Built from the parts rather than midnight plus minutes, so the day the clocks change is right too.
export function msOf(iso: string, time: string): number {
  const [y, mo, d] = iso.split('-').map(Number)
  const [h, m] = time.split(':').map(Number)

  return new Date(y!, mo! - 1, d!, h!, m!).getTime()
}

function hhmm(time: string): string {
  return time.padStart(5, '0')
}

function pad(n: number): string {
  return String(n).padStart(2, '0')
}

