files.types/index.d.ts:
/** A lesson on one day: one period, or a double the same class runs on into. */
export type Lesson = {
  /** As the timetable names it: "Upper Sixth", "Supervised study", "Cover". */
  cls: string
  /** The first and last period, the same for a single. */
  from: number
  to: number
  /** "HH:MM", local time. */
  start: string
  end: string
  /** "YYYY-MM-DD". */
  date: string
}

export type Period = { p: number; start: string; end: string; wedStart?: string }

/** The timetable file as the strip reads it. */
export type Timetable = {
  periods: Period[]
  /** Day ("Mon") to period ("4") to the class taught then. */
  week: Record<string, Record<string, string>>
  /** Rotation days: period n runs the lesson of the nth slot listed. */
  oneOff: { date: string; runs: { day: string; p: number }[] }[]
  /** Terms and breaks; a day inside a break has no lessons. */
  terms: { what: string; from: string; to: string; hasLessons: boolean }[]
}

/** One task of a lesson's run sheet, as a planning window hands it over. */
export type RunTask = {
  title: string
  minutes: number
  /** One word for the chip on its bar: "Quiz", "Starter", "Essay". */
  label?: string
  /** A quiz or exam question's marks: a tick each on its bar (one mark, one minute). */
  marks?: number
  /** "HH:MM" when the plan gives it. */
  start?: string
  /** One sentence: what the pupils do. */
  detail?: string
}

/** A lesson's run sheet: its tasks in order. */
export type LessonRun = { cls: string; date: string; period: string; tasks: RunTask[]; savedAt: number }

/** The task the teacher pressed ▶ on, when, and when they pressed ✓ if they ended it early: the lesson moves at his pace. */
export type Play = { key: string; task: number; at: number; endedAt?: number }

declare module 'claude-code' {
  interface PluginState {
    /**
     * `timetable`: the file as last read; `problem`: why it could not be read; `minute`: the clock the strip
     * redraws on; `isHidden`: /lessons hide; `runs`, `play`, `beat`, `trial`: the lesson's tasks, as below.
     */
    'next-lesson': {
      timetable: Timetable | null
      problem: string
      minute: number
      isHidden: boolean
      /** The run sheets planning windows handed over, from the shared runs file. */
      runs: LessonRun[]
      /** The task running in the lesson on screen, or null before the teacher starts one. */
      play: Play | null
      /** Moves when a running task's bar fills, so the card redraws with its next task. */
      beat: number
      /** /lessons try: a pretend lesson of three one-minute tasks, to see and hear the strip at work. */
      trial: { lesson: Lesson; run: LessonRun } | null
    }
  }
}
